update perks set name = name || ' |cs| ' || $cs$Ohýbání vzduchu$cs$ where id = 'air-bending' and name not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Můžeš omezeně ovládat vzduch. Dokážeš vytvořit malé poryvy větru, ovládat existující proudění vzduchu a vytvářet drobné vzdušné účinky, třeba zvednout větrem lehké předměty nebo vyvolat vánek. Můžeš taky vytvořit malý magický náraz vzduchu, který dokáže bytosti odstrčit.$cs$ where id = 'air-bending' and description not like '%|cs|%';
update perks set range = range || ' |cs| ' || $cs$Sebe/2 metry$cs$ where id = 'air-bending' and range not like '%|cs|%';
