update perks set name = name || ' |cs| ' || $cs$Vetřelci$cs$ where id = 'aliens' and name not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Máš tajuplnou schopnost vycítit tvory, kteří do okolí nepatří. Dokážeš určit, kde takové bytosti jsou, do vzdálenosti hodiny chůze.$cs$ where id = 'aliens' and description not like '%|cs|%';
update perks set flavour = flavour || ' |cs| ' || $cs$Rukama jim prošlo mnoho artefaktů; vědí, z čeho jsou udělané.$cs$ where id = 'ancient-artisan' and flavour not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Můžeš se pokusit odhalit magii vloženou do vyrobeného artefaktu, i když nejsi Zaříkávač. Poznáš, jestli v něm magie je a z jaké magické dovednosti pochází. Přesný účinek určit nedokážeš.$cs$ where id = 'ancient-artisan' and description not like '%|cs|%';
update perks set name = name || ' |cs| ' || $cs$Androgyn$cs$ where id = 'androgynous' and name not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Dokážeš se přestrojit za jiné pohlaví a rychle mezi takovými přestrojeními přepínat. Perk neplatí, když máš znak, který pohlaví prozrazuje, třeba vousy.$cs$ where id = 'androgynous' and description not like '%|cs|%';
update perks set name = name || ' |cs| ' || $cs$Ovládnutí zvířete$cs$ where id = 'animal-control' and name not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Dokážeš se vtělit do zvířete, které vidíš, a úplně ho ovládnout. Dokud ho ovládáš, ztratíš spojení se svým tělem. Zvíře můžeš ovládat, i když se ti brání, ale každé kolo musíš uspět, aby se spojení nepřetrhlo.$cs$ where id = 'animal-control' and description not like '%|cs|%';
update perks set range = range || ' |cs| ' || $cs$Zvíře poblíž$cs$ where id = 'animal-control' and range not like '%|cs|%';
