update perks set flavour = flavour || ' |cs| ' || $cs$Jejich rychlost je nelidská. V jediném okamžiku dokážou zaútočit na dva nepřátele.$cs$ where id = 'battle-reflexes' and flavour not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Když v boji zblízka útočíš na dva nepřátele ve svém dosahu, můžeš použít manévr Rozsáhle zdarma.$cs$ where id = 'battle-reflexes' and description not like '%|cs|%';
