update perks set range = range || ' |cs| ' || $cs$Dohled$cs$ where id = 'beast-mind' and range not like '%|cs|%';
update perks set flavour = flavour || ' |cs| ' || $cs$Nikdo neví, jaké je to být smutným elfem…$cs$ where id = 'behind-blue-eyes' and flavour not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Prošel jsi větší bolestí, než si většina dokáže představit. Když si vezmeš Jizvu na Duši, abys odvrátil neúspěch, dá ti místo 2 bodů 3.$cs$ where id = 'behind-blue-eyes' and description not like '%|cs|%';
update perks set name = name || ' |cs| ' || $cs$Znamení Berkano$cs$ where id = 'berkano-sign' and name not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Vědmácké znamení, které ruší magické účinky. Když ho aktivuješ, zlomíš jedno kouzlo nebo magický účinek mířící na tebe. Na následky magie (třeba hořící zem) nefunguje. Spojence jím nekryješ. Znamení můžeš použít jako součást manévru Obrana.$cs$ where id = 'berkano-sign' and description not like '%|cs|%';
update perks set range = range || ' |cs| ' || $cs$Sebe$cs$ where id = 'berkano-sign' and range not like '%|cs|%';
update perks set name = name || ' |cs| ' || $cs$Požehnání a kletby$cs$ where id = 'blessings-and-curses' and name not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Můžeš vytvořit prosté kouzlo, které cíli pomůže, nebo ho omezí. Kletba nemůže udělit přímé zranění, ale může ovlivnit jakýkoli druh hodu, který cíl hází. Obvykle má podobu jako „ať je tvá muška přesná“ nebo „ať se ti zaplete jazyk“. Výsledkem může být výhoda nebo nevýhoda u každého hodu určitého druhu, nebo bonusová kostka k4 pro cíl.

Trvá do nejbližšího soumraku nebo úsvitu. Cíl může nést jen jedno požehnání nebo kletbu naráz: nové nahradí staré.$cs$ where id = 'blessings-and-curses' and description not like '%|cs|%';
