update perks set description = description || ' |cs| ' || $cs$Vrhneš záblesk jasného světla do bodu v dosahu. Každý do 5 metrů od toho bodu si hází obranný hod; kdo prohraje, je na dvě kola Oslepený.$cs$ where id = 'blinding-lights' and description not like '%|cs|%';
