update perks set description = description || ' |cs| ' || $cs$Kdykoli se pokoušíš kopat, těžit nebo se prohrabávat, máš výhodu. Kopeš, těžíš a hrabeš taky dvakrát rychleji než obvykle.$cs$ where id = 'call-of-the-mine' and description not like '%|cs|%';
