update perks set name = name || ' |cs| ' || $cs$Okouzlení$cs$ where id = 'charm' and name not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Můžeš se pokusit okouzlit humanoida, kterého vidíš v dosahu. Brání se obranným hodem, s výhodou, pokud s ním ty nebo tví spojenci bojujete. Když prohraje, je tebou okouzlený, dokud kouzlo neskončí nebo dokud ty nebo tví spojenci neuděláte něco, co mu ublíží. Okouzlený tvor tě považuje za přátelského známého. Když kouzlo skončí, ví, že jsi ho okouzlil.$cs$ where id = 'charm' and description not like '%|cs|%';
