update perks set description = description || ' |cs| ' || $cs$Můžeš rozhodnout, že ve tvém okolí ve městě je jakékoli místo nebo prvek typický pro to prostředí (třeba slepá ulička, hřbitov, hospoda, socha, stoky nebo tržiště).$cs$ where id = 'city-guide' and description not like '%|cs|%';
update perks set flavour = flavour || ' |cs| ' || $cs$Pocházejí z rozvětveného klanu, takže mají víc bratranců a příbuzných, než dokážou spočítat.$cs$ where id = 'clan-bond' and flavour not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Pokaždé, když potkáš trpaslíka, můžeš rozhodnout, že je to tvůj vzdálený příbuzný nebo že jeho klan má k tomu tvému nějaký závazek.$cs$ where id = 'clan-bond' and description not like '%|cs|%';
update perks set cost_unit = cost_unit || ' |cs| ' || $cs$za 5 obnoveného Těla$cs$ where id = 'clay-mender' and cost_unit not like '%|cs|%';
