update perks set description = description || ' |cs| ' || $cs$Dokážeš komunikovat s rostlinami, zemí a vodou. Díky tomu můžeš udělat jedno z následujícího: i) okamžitě získat znalost o okolí (třeba jestli tu jsou nějaká nebezpečí, zdroje vody, užitečné rostliny); ii) zeptat se na cokoli z minulosti cíle. Znalost cíle je ale omezená na to, co sám přímo zažil (rostliny vnímají tlak, světlo a teplotu; kameny tlak, teplotu a otřesy).$cs$ where id = 'commune-with-nature' and description not like '%|cs|%';
