update perks set description = description || ' |cs| ' || $cs$Dokážeš vytvořit až 10 litrů čisté vody v prostoru 1 krychlového metru, nebo stejné množství vody ve stejně velkém prostoru zničit. Vytvořená voda je čistá a pitná. Může spadnout naráz, nebo jako déšť během 10 minut. Zničením vody můžeš taky rozpustit mlhu nebo vysušit vlhko v oblasti.$cs$ where id = 'create-or-destroy-water' and description not like '%|cs|%';
