update perks set description = description || ' |cs| ' || $cs$Když útočíš zbraní na dálku, můžeš bonusovou akcí zaútočit stejnou zbraní ještě jednou. Podmínkou je volný výstřel a snadno dostupná munice.$cs$ where id = 'double-shot' and description not like '%|cs|%';
