update perks set description = description || ' |cs| ' || $cs$Když držíš dvě zbraně na boj zblízka, můžeš bonusovou akcí zaútočit ještě jednou zbraní ve vedlejší ruce. Tenhle perk můžeš použít jen jednou za tah.$cs$ where id = 'double-trouble' and description not like '%|cs|%';
