update perks set description = description || ' |cs| ' || $cs$Dokážeš vstoupit do snů spícího cíle a manipulovat jimi. Můžeš do nich zasadit návrhy, vytáhnout informace nebo cíl prostě trýznit. Cíl si může každé kolo hodit obranný hod, aby se tvému vpádu ubránil. Probudí se, když mu ve snu jakkoli ublížíš, a po probuzení si sen živě pamatuje, včetně tvé tváře, pokud jsi mu ji ukázal.$cs$ where id = 'dream-eater' and description not like '%|cs|%';
