update perks set description = description || ' |cs| ' || $cs$Máš výhodu při skrývání a plížení, dokud není dost světla.$cs$ where id = 'dusk-veil' and description not like '%|cs|%';
update perks set name = name || ' |cs| ' || $cs$Ohýbání země$cs$ where id = 'earth-bending' and name not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Můžeš omezeně ovládat zemi. Dokážeš vyvolat otřesy a drobné zemní účinky (třeba vztyčit malé zídky z hlíny nebo vytvořit jámy), nechat zemi levitovat, najít nerosty, rozštípnout skalní útvar a vnořit věci do kamene nebo země, jako by to byla voda. Všechna země musí být v přirozené podobě. Zemi nedokážeš vytvořit z ničeho a tahle manipulace nezpůsobuje žádné přímé zranění.$cs$ where id = 'earth-bending' and description not like '%|cs|%';
update perks set name = name || ' |cs| ' || $cs$Zemětřesení$cs$ where id = 'earthquake' and name not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Vyvoláš místní zemětřesení v poloměru 5 metrů kolem bodu v dosahu. Země se prudce otřásá, slabé stavby praskají a tvorové ztrácejí půdu pod nohama. Každý tvor v oblasti si hází obranný hod; kdo prohraje, spadne k zemi a dostane drtivé zranění (NPC, které vyhraje, dostane polovinu, hráčská postava, která vyhraje, nic). Když kouzlo udržíš déle než jedno kolo, začnou se v zemi otevírat pukliny.$cs$ where id = 'earthquake' and description not like '%|cs|%';
update perks set range = range || ' |cs| ' || $cs$30 metrů$cs$ where id = 'earthquake' and range not like '%|cs|%';
update perks set area = area || ' |cs| ' || $cs$Poloměr 5 metrů (statek)$cs$ where id = 'earthquake' and area not like '%|cs|%';
