update perks set description = description || ' |cs| ' || $cs$Máš výhodu v pěším boji zblízka proti lidem a zvířatům, když bojuješ beze zbraně nebo s improvizovanou zbraní: pěstmi, lahví, nohou od židle.$cs$ where id = 'fight-club' and description not like '%|cs|%';
update perks set name = name || ' |cs| ' || $cs$Ohýbání ohně$cs$ where id = 'fire-bending' and name not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Můžeš omezeně ovládat oheň. Dokážeš zapálit hořlavé předměty, uhasit malé ohně a tvarovat existující plameny. Dokážeš taky ovládat existující kouř. Můžeš vytvořit i malé magické ohníčky. Všechny tyhle ohně vycházejí z tvého těla a nedají se vytvořit z ničeho. Když se dotknou nějaké bytosti, udělí malé ohnivé zranění. Účinek ohně se dá přirovnat k plameni pochodně.$cs$ where id = 'fire-bending' and description not like '%|cs|%';
