update perks set name = name || ' |cs| ' || $cs$Ohnivý štít$cs$ where id = 'fire-shield' and name not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Vytvoříš magický štít z tenkých plamenů, které ti ovinou tělo a dají ti odolnost vůči zranění ledem a útokům zblízka. Když štít někdo zasáhne, rozbije se a udělí útočníkovi ohnivé zranění. Můžeš místo toho vytvořit studený ohnivý štít, který dává odolnost vůči zranění ohněm a útočníkům uděluje zranění ledem.$cs$ where id = 'fire-shield' and description not like '%|cs|%';
