update perks set description = description || ' |cs| ' || $cs$Vrhneš ohnivou kouli, která při dopadu exploduje a udělí ohnivé zranění každému do 4 metrů od místa dopadu. Každý si hází obranný hod: NPC, které vyhraje, dostane poloviční zranění, hráčská postava, která vyhraje, žádné.$cs$ where id = 'fireball' and description not like '%|cs|%';
