update perks set description = description || ' |cs| ' || $cs$Perk má dva účinky: i) vycítíš, když je poblíž netvor, zhruba do 100 metrů, i bez jakéhokoli prozrazení (jen pocit: žádný směr, žádný počet); ii) dokážeš bojovat s netvory a zvířaty, i když ti běžné smysly nepomáhají (třeba v naprosté tmě nebo husté mlze).$cs$ where id = 'hunter-instinct' and description not like '%|cs|%';
