update perks set description = description || ' |cs| ' || $cs$Dokážeš si neomylně vytvořit falešnou identitu, i s doklady, vzhledem a minulostí. Podmínkou je, že máš na přípravu aspoň jeden den a utratíš 25 stříbrných. Když identitu přijmeš, všichni tvorové věří, že jsi ten, za koho se vydáváš, pokud nemají zjevný důvod ti nevěřit. Konkrétního člověka tímhle perkem napodobit nemůžeš.$cs$ where id = 'infiltration-expertise' and description not like '%|cs|%';
