update perks set description = description || ' |cs| ' || $cs$Dokážeš se vtělit do zvířete, které je k tobě přátelské. Ve vtělení vnímáš svět tělem zvířete a cítíš jeho emoce. Můžeš mu dávat pokyny, ale přímo ho ovládat nemůžeš. Dokud jsi vtělený, ztratíš vládu nad svým tělem a nevíš, v jakém je stavu.$cs$ where id = 'invisible-rider' and description not like '%|cs|%';
