update perks set description = description || ' |cs| ' || $cs$Dokážeš vyrobit jednoduchou past nebo oko z improvizovaných materiálů, které najdeš v okolí (třeba z toho, co na místě nasbíráš). Síla pasti může být až do výše tvé zásoby Duše. Na nastražení pasti potřebuješ aspoň 10 minut.$cs$ where id = 'macgyver' and description not like '%|cs|%';
