update perks set description = description || ' |cs| ' || $cs$Když bojuješ ze sedla, můžeš bonusovou akcí použít své jízdní zvíře a buď i) srazit k zemi všechny cíle do 1 metru, nebo ii) cíl převálcovat, udělit mu 1k6 zranění a odhodit ho o 1 metr. Ze sedla máš taky manévr Rozsáhle zdarma u zastrašování.$cs$ where id = 'rider' and description not like '%|cs|%';
