update perks set description = description || ' |cs| ' || $cs$Máš výhodu u Mořeplavby: řízení lodi, zacházení s lanovím a posádkou, navigace na otevřeném moři a čtení moře a počasí na moři.$cs$ where id = 'sea-legs' and description not like '%|cs|%';
update perks set name = name || ' |cs| ' || $cs$Seismický smysl$cs$ where id = 'seismic-sense' and name not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Po seslání vnímáš otřesy v zemi a odhalíš přítomnost tvorů a předmětů do 30 metrů. Dokážeš určit polohu a pohyb těch bytostí, i když jsou skryté nebo neviditelné. Rozeznáš o nich ale jen obecné podrobnosti (třeba počet a přibližnou velikost). Vnímáš taky uspořádání okolního terénu, včetně překážek a staveb, a dokážeš se podle něj orientovat v úplné tmě.$cs$ where id = 'seismic-sense' and description not like '%|cs|%';
update perks set range = range || ' |cs| ' || $cs$30 metrů$cs$ where id = 'seismic-sense' and range not like '%|cs|%';
