update perks set name = name || ' |cs| ' || $cs$Bystré smysly$cs$ where id = 'sharp-senses' and name not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Máš výhodu při všímání si věcí zrakem, sluchem nebo čichem, a pokud ti nic nebrání ve výhledu, dokážeš prozkoumat vzdálený výhled i za nepříznivých podmínek. Dokážeš taky zadržet dech dvakrát déle než obvykle.$cs$ where id = 'sharp-senses' and description not like '%|cs|%';
