update perks set description = description || ' |cs| ' || $cs$Když bojuješ v blízkosti jiné postavy, můžeš svým Tělem platit za její manévry a odvracet její neúspěchy.$cs$ where id = 'shoulder-on-shoulder' and description not like '%|cs|%';
