update perks set description = description || ' |cs| ' || $cs$Můžeš vytvořit obrazec se strážnou bytostí, která obrazec probudí, jen když se splní určitá podmínka (třeba když se znaku dotkne někdo konkrétní, nebo když někdo řekne heslo).$cs$ where id = 'sigil-guardian' and description not like '%|cs|%';
update perks set name = name || ' |cs| ' || $cs$Kožoměnec$cs$ where id = 'skinchanger' and name not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Když vlastníš něco, co kdysi patřilo zvířeti, můžeš se v to zvíře proměnit. Zachováš si zásoby zdrojů i úrovně povolání a získáš zvláštní schopnosti zvířete, ale tvé akce omezují schopnosti nového těla (ve vlčím těle třeba nepáčíš zámky).$cs$ where id = 'skinchanger' and description not like '%|cs|%';
update perks set range = range || ' |cs| ' || $cs$Sebe$cs$ where id = 'skinchanger' and range not like '%|cs|%';
