update perks set description = description || ' |cs| ' || $cs$Ohýbání vody teď můžeš použít i na vodu upravenou lidskou rukou nebo pocházející z lidí, třeba víno v láhvi, polévku v misce nebo louži krve. Vodu v živých bytostech ale ohýbat nemůžeš.$cs$ where id = 'soul-of-water' and description not like '%|cs|%';
update perks set name = name || ' |cs| ' || $cs$Znamení Sowilo$cs$ where id = 'sowilo-sign' and name not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Vědmácké znamení, které kolem tebe vyvolá záblesk jasného světla. Každý jiný do 5 metrů od tebe si hází obranný hod; kdo prohraje, je na dvě kola Oslepený. Vlastní znamení tě nikdy neoslepí, ale spojence stojící blízko ano.$cs$ where id = 'sowilo-sign' and description not like '%|cs|%';
