update perks set description = description || ' |cs| ' || $cs$Když vystupujete jako skupina, můžeš manévrem Obrana čelit akcím proti ostatním účinkujícím. Ostatní můžou tvým Vlivem odvracet své vlastní neúspěchy. Můžeš taky použít manévr Rozsáhle zdarma.$cs$ where id = 'starting-a-band' and description not like '%|cs|%';
