update perks set description = description || ' |cs| ' || $cs$Vědmácké znamení, které funguje jako dočasný štít. Do konce konfliktu můžeš používat manévr Obrana, jak často chceš, a neplatit za něj. Jen ti dovolí se bránit: prohraný obranný hod se pořád musí odvrátit jako obvykle, vyčerpáním nebo Jizvou.$cs$ where id = 'tiwaz-sign' and description not like '%|cs|%';
