update perks set description = description || ' |cs| ' || $cs$Když vstoupíš do konfliktu s netvorem, kterého jsi už jednou porazil, získáš dvě bonusové kostky, které v konfliktu můžeš použít (podle úrovně Hraničáře: 1 k4, 2 k6, 3 k8, 4 k10, 5 k12).$cs$ where id = 'trophy-hunter' and description not like '%|cs|%';
