update perks set name = name || ' |cs| ' || $cs$Dvě mouchy$cs$ where id = 'two-birds' and name not like '%|cs|%';
update perks set description = description || ' |cs| ' || $cs$Po útoku vrhací zbraní můžeš bonusovou akcí hodit druhou, na stejný cíl nebo jiný. Podmínkou je, že máš druhou zbraň snadno po ruce.

Druhý hod je samostatný útok, takže může mít vlastní manévr.$cs$ where id = 'two-birds' and description not like '%|cs|%';
