update perks set description = description || ' |cs| ' || $cs$Můžeš omezeně ovládat vodu ve všech jejích přirozených podobách. Dokážeš vytvořit vlny, ovládat existující proudy, vytáhnout vodu ze země, měnit její skupenství a nechat ji levitovat nebo ji vystřelit na lidi. Vycítíš přítomnost vody. Vodu nedokážeš vytvořit z ničeho a tahle manipulace nezpůsobuje žádné přímé zranění.$cs$ where id = 'water-bending' and description not like '%|cs|%';
