update perks set description = description || ' |cs| ' || $cs$Vycítíš, když je poblíž netvor, běs nebo nemrtvý, zhruba do 100 metrů. Je to jen pocit: žádný směr, žádný počet. Ty největší nadpřirozené bytosti vycítit nejde.$cs$ where id = 'witcher-senses' and description not like '%|cs|%';
