update perks set description = description || ' |cs| ' || $cs$Dokážeš vyrobit kontaktní jed, který působí i na holé kůži, nejen skrz ránu, ústa nebo oči. Za 1 Materiál navíc za stupeň síly na tebe jed nepůsobí, takže ho můžeš nosit na kůži a rtech a šířit dotykem nebo polibkem.$cs$ where id = 'your-lips-are-venomous-poison' and description not like '%|cs|%';
update perks set cost_unit = cost_unit || ' |cs| ' || $cs$za stupeň síly (3, pokud jsi imunní)$cs$ where id = 'your-lips-are-venomous-poison' and cost_unit not like '%|cs|%';
